import Foundation
import Testing
@testable import VoiceCore
final class FakeRunner: ProcessRunner, @unchecked Sendable {
    var result:ProcessResult; var codexAnswer:String?; private(set) var calls:[(executable:String,arguments:[String],stdin:String,workingDirectory:URL?,timeout:TimeInterval)]=[]; var results:[String:ProcessResult]=[:]
    init(result:ProcessResult = .init(exitCode:0,stdout:"",stderr:""),codexAnswer:String?=nil){self.result=result;self.codexAnswer=codexAnswer}
    func run(executable:String,arguments:[String],stdin:String,workingDirectory:URL?,timeout:TimeInterval) async throws -> ProcessResult { calls.append((executable,arguments,stdin,workingDirectory,timeout)); if let codexAnswer,let i=arguments.firstIndex(of:"--output-last-message"){try codexAnswer.write(toFile:arguments[i+1],atomically:true,encoding:.utf8)}; return results[(arguments+[executable]).joined(separator:" ")] ?? result }
}
